'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {hotelRpc,usd,type Booking} from '@/lib/pilot';

type RequestState='pending'|'leased'|'retry'|'awaiting_sync'|'review'|'synced';
type Status={found:boolean;request_id?:string;reservation_id?:string;state?:RequestState;expected_source_version?:number;arrival?:string;departure?:string;result_code?:string|null;applied_source_version?:number|null;submitted_at?:string;updated_at?:string};
type SavedRequest={request_id:string;expected_source_version:number;arrival:string;departure:string};
type Props={actor:string;tenant:string;property:string;role:string;booking:Booking;businessDate:string;disabled?:boolean;onBusyChange:(busy:boolean)=>void;onSaved:(status:Status)=>Promise<void>};
const key=(p:Props)=>'iratepilot-pms-pending-ota-stay-change:'+p.actor+':'+p.tenant+':'+p.property+':'+p.booking.id;
function validSaved(value:unknown):value is SavedRequest{return !!value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).sort().join(',')==='arrival,departure,expected_source_version,request_id'&&typeof(value as SavedRequest).request_id==='string'&&Number.isSafeInteger((value as SavedRequest).expected_source_version)&&typeof(value as SavedRequest).arrival==='string'&&typeof(value as SavedRequest).departure==='string'}
function restoreSavedRequest(storageKey:string){try{if(typeof window==='undefined')return {request:null,blocked:false,error:''};const raw=window.sessionStorage.getItem(storageKey);if(!raw)return {request:null,blocked:false,error:''};const value=JSON.parse(raw);if(validSaved(value))return {request:value,blocked:false,error:''};throw Error('Invalid saved request')}catch{return {request:null,blocked:true,error:'A saved OTA date-change request could not be read. Do not submit another request until it is recovered or cleared by a manager.'}}}
function stateLabel(state:RequestState){return ({pending:'Queued for iRatePilot.com',leased:'Sending to iRatePilot.com',retry:'Delivery retry scheduled',awaiting_sync:'OTA accepted; waiting for PMS sync',review:'Needs manager review',synced:'Dates updated and synchronized'} as const)[state]}
function formatDate(value?:string){return value?new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z')):'—'}

export function OtaStayChangeRequest(props:Props){
 const storageKey=key(props),[initialRequest]=useState(()=>restoreSavedRequest(storageKey));
 const [arrival,setArrival]=useState(initialRequest.request?.arrival??props.booking.arrival??''),[departure,setDeparture]=useState(initialRequest.request?.departure??props.booking.departure??''),[status,setStatus]=useState<Status|null>(null),[savedRequest,setSavedRequest]=useState<SavedRequest|null>(initialRequest.request),[busy,setBusy]=useState(false),[loadingStatus,setLoadingStatus]=useState(true),[storageBlocked,setStorageBlocked]=useState(initialRequest.blocked),[error,setError]=useState(initialRequest.error),[notice,setNotice]=useState('');
 const lock=useRef(false),alive=useRef(true),reportedSync=useRef(''),onSavedRef=useRef(props.onSaved),onBusyChangeRef=useRef(props.onBusyChange);
 useEffect(()=>{onSavedRef.current=props.onSaved},[props.onSaved]);
 useEffect(()=>{onBusyChangeRef.current=props.onBusyChange},[props.onBusyChange]);
 useEffect(()=>()=>{alive.current=false;if(lock.current)onBusyChangeRef.current(false)},[]);
 const readStatus=useCallback(async()=>{try{const value=await hotelRpc<Status>('ota_stay_change_status',{p_tenant:props.tenant,p_property:props.property,p_reservation:props.booking.id});if(!alive.current)return;setStatus(value.found?value:null);if(value.found&&value.state==='synced'&&reportedSync.current!==value.request_id){reportedSync.current=value.request_id??'';try{await onSavedRef.current(value)}catch{if(alive.current)setError('The OTA change is synchronized. Refresh the workspace to reload this reservation.')}}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to check the OTA change status.')}finally{if(alive.current)setLoadingStatus(false)}},[props.tenant,props.property,props.booking.id]);
 const refreshStatus=useCallback(async()=>{if(!alive.current)return;setLoadingStatus(true);setError('');await readStatus()},[readStatus]);
 useEffect(()=>{const timer=setTimeout(()=>void readStatus(),0);return()=>clearTimeout(timer)},[readStatus]);
 const statusState=status?.state;
 useEffect(()=>{if(!['pending','leased','retry','awaiting_sync'].includes(statusState??''))return;const timer=setInterval(refreshStatus,15000);return()=>clearInterval(timer)},[statusState,refreshStatus]);
 function start(){if(lock.current)return false;lock.current=true;setBusy(true);props.onBusyChange(true);setError('');setNotice('');return true}
 function finish(){lock.current=false;if(alive.current){setBusy(false);props.onBusyChange(false)}}
 async function send(value:SavedRequest){if(!start())return;try{sessionStorage.setItem(key(props),JSON.stringify(value))}catch{setStorageBlocked(true);setError('Browser session storage is unavailable. Enable it before sending so an interrupted date-change request can be safely recovered.');finish();return}setSavedRequest(value);try{await hotelRpc('request_ota_stay_change',{p_tenant:props.tenant,p_property:props.property,p_reservation:props.booking.id,p_request:value.request_id,p_expected_source_version:value.expected_source_version,p_arrival:value.arrival,p_departure:value.departure});try{sessionStorage.removeItem(key(props))}catch{}setSavedRequest(null);setStatus({found:true,request_id:value.request_id,reservation_id:props.booking.id,state:'pending',expected_source_version:value.expected_source_version,arrival:value.arrival,departure:value.departure});setNotice('Request received. The PMS will keep the current dates until iRatePilot.com accepts the change and sends the updated reservation back.');await refreshStatus()}catch(e){const code=e&&typeof e==='object'&&'code'in e?String(e.code):'';const message=e instanceof Error?e.message:'Unable to submit the date-change request.';if(!code||code==='40003'||code==='57014'){setError('The result is uncertain. Keep the original request and retry it exactly; do not create a second request. '+message)}else{try{sessionStorage.removeItem(key(props))}catch{}setSavedRequest(null);setError(message)}}finally{finish()}}
 const canRequest=props.role==='owner'||props.role==='manager';const active=status&&status.state!=='synced';const invalid=!arrival||!departure||arrival<=props.businessDate||departure<=arrival||(arrival===props.booking.arrival&&departure===props.booking.departure);
 return <section className="pilot-ota-date-change" aria-labelledby="ota-change-heading">
  <h3 id="ota-change-heading">Request iRatePilot.com date change</h3>
  <p>This reservation is managed by iRatePilot.com. An owner or manager can request new dates. Its stay value and payment stay unchanged; if the OTA recalculates price, the request goes to review without changing this PMS reservation.</p>
  {status&&<output className={'pilot-notice '+(status.state==='review'?'amber':'')}><strong>{stateLabel(status.state!)}</strong><span>{formatDate(status.arrival)} to {formatDate(status.departure)}{status.state==='review'&&status.result_code?` · ${status.result_code}`:''}</span>{status.state==='awaiting_sync'&&<span>The OTA accepted the request. Waiting for its updated reservation snapshot before changing PMS dates.</span>}</output>}
  {notice&&<output>{notice}</output>}{error&&<div className="pilot-error" role="alert">{error}</div>}
  <button type="button" className="text-button" disabled={busy||loadingStatus||props.disabled} onClick={()=>void refreshStatus()}>{loadingStatus?'Checking status…':'Refresh request status'}</button>
  {!canRequest?<p>Only an owner or manager can submit an OTA date change.</p>:storageBlocked?<p>Recover or clear the browser’s saved request before making another change.</p>:status?.state==='review'?<p>Resolve this request with iRatePilot support before submitting another change. The existing request is preserved for audit.</p>:active&&!savedRequest?<p>This request must finish or be reviewed before another stay change can be submitted.</p>:savedRequest?<><p role="alert">An earlier submission may have reached iRatePilot.com. Retry only this exact request.</p><button type="button" className="primary" disabled={busy||props.disabled} onClick={()=>void send(savedRequest)}>{busy?'Retrying…':'Retry exact date-change request'}</button></>:<form onSubmit={e=>{e.preventDefault();if(invalid||busy||loadingStatus||active||props.disabled||storageBlocked)return;void send({request_id:crypto.randomUUID(),expected_source_version:props.booking.source_version,arrival,departure})}}>
   <div className="form-grid"><label className="field">New arrival<input aria-label="New arrival" type="date" min={props.businessDate} required value={arrival} disabled={busy||loadingStatus||active||props.disabled} onChange={e=>setArrival(e.target.value)}/></label><label className="field">New departure<input aria-label="New departure" type="date" min={props.businessDate} required value={departure} disabled={busy||loadingStatus||active||props.disabled} onChange={e=>setDeparture(e.target.value)}/></label></div>
   <p>Current stay value: <strong>{usd(props.booking.guest_total_minor)}</strong>. No extra payment, refund, tax, or fee adjustment is made by this request.</p>
   <label className="pilot-check"><input type="checkbox" required disabled={busy||loadingStatus||active||props.disabled}/>I reviewed the new dates and understand the OTA must accept them before the PMS updates.</label>
   <button className="primary" disabled={busy||loadingStatus||active||props.disabled||invalid}>{busy?'Submitting…':'Send date-change request'}</button>
  </form>}
 </section>
}
